INSERT IGNORE INTO `base_translation` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3003, 'fr-FR', '<h2>Politique de confidentialité</h2><p>Merci d’utiliser cette application. Nous respectons et protégeons vos données personnelles et ne les traitons que dans la mesure nécessaire à la connexion au compte, aux fonctionnalités de l’application et au service client.</p><h3>I. Utilisation des informations</h3><p>Nous utilisons vos informations conformément aux lois applicables et à cette politique, et ne les utilisons pas à des fins étrangères.</p><h3>II. Vos droits</h3><p>Vous pouvez consulter, rectifier ou supprimer vos données personnelles conformément à la loi, ou nous contacter via les canaux publiés dans l’application.</p>');
INSERT IGNORE INTO `base_translation` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3004, 'fr-FR', '<h2>Conditions d’utilisation</h2><p>Bienvenue dans cette application. Veuillez lire et comprendre le présent accord et les règles associées avant de l’utiliser. L’utilisation des services de l’application vaut acceptation de ces conditions.</p><h3>I. Utilisation du service</h3><p>Utilisez chaque fonctionnalité légalement et conformément aux indications de la page. Il est interdit d’utiliser cette application pour des activités illégales ou portant atteinte aux droits d’autrui.</p><h3>II. Modification de l’accord</h3><p>Nous pouvons mettre à jour cet accord selon l’évolution de l’activité et de la réglementation, puis afficher la version mise à jour dans l’application.</p>');
